const expectedProducts = {
    'Sauce Labs Fleece Jacket': '$49.99',
    'Sauce Labs Backpack': '$29.99',
    'Sauce Labs Bolt T-Shirt': '$15.99',
    'Test.allTheThings() T-Shirt (Red)': '$15.99',
    'Sauce Labs Bike Light': '$9.99',
    'Sauce Labs Onesie': '$7.99'
}

// Generated by Cypress Author on 2026-11-26.
// Décrire le scénario de tri des produits Swag Labs.
describe('Swag Labs product sorting', () => {
    // Préparer une session utilisateur avant le scénario.
    beforeEach(() => {
        // Se connecter avec la commande partagée.
        cy.login();
    });

    // Fermer la session après le scénario.
    afterEach(() => {
        // Se déconnecter avec la commande partagée.
        cy.logout();
    });

    // Déclarer le scénario Price high to low à compléter.
    it('sorts products by price from high to low', () => {
        cy.get('[data-test="product-sort-container"]').select('Price (high to low)');
        // Vérifier que le menu de tri sélectionne l'ordre Name de Z to A.
        cy.get('[data-test="product-sort-container"]').should('have.value', 'hilo');

        // Vérifier que l'inventaire contient le même ordre et nombre de produits.
        cy.get('.inventory_item').should('have.length', 6).then((items) => {
            const firstProduct = items.first();
            const lastProduct = items.last();

            const firstProdName = firstProduct.find('.inventory_item_name').text().trim();
            const firstProdPrice = firstProduct.find('.inventory_item_price').text().trim();

            const lastProdName = lastProduct.find('.inventory_item_name').text().trim();
            const lastProdPrice = lastProduct.find('.inventory_item_price').text().trim();

            expect(firstProdName).to.equal('Sauce Labs Fleece Jacket');
            expect(firstProdPrice).to.equal(expectedProducts[firstProdName]);
            cy.log("First Price: " + expectedProducts[firstProdName]);
            cy.task('log', "First Price: " + expectedProducts[firstProdName]);

            expect(lastProdName).to.equal('Sauce Labs Onesie');
            expect(lastProdPrice).to.equal(expectedProducts[lastProdName]);
            cy.log("Last Price: " + expectedProducts[lastProdName]);
            cy.task('log', "First Price: " + expectedProducts[lastProdName]);
        });
    });
});
